import json, hashlib, uuid

def make_guid(seed):
    h = hashlib.sha256(seed.encode()).hexdigest()
    return str(uuid.UUID(h[:32]))

with open('semio/assets/semio/kit_metabolism_diffed.json', 'r') as f:
    kit = json.load(f)

design = next((d for d in kit['designs'] if d['name'] == 'Nakagin Capsule Tower'), None)
if design:
    layers = []
    tower_guid = make_guid('nakagin-capsule-tower/tower')
    layers.append({
        'guid': tower_guid,
        'path': 'tower',
        'attributes': [{'key': 'ifc.type', 'value': 'IfcBuilding'}]
    })
    for i in range(11):
        storey_guid = make_guid(f'nakagin-capsule-tower/tower/{i}')
        layers.append({
            'guid': storey_guid,
            'path': f'tower/{i}',
            'attributes': [{'key': 'ifc.type', 'value': 'IfcBuildingStorey'}]
        })
    design['layers'] = layers
    with open('semio/assets/semio/kit_metabolism_diffed.json', 'w') as f:
        json.dump(kit, f, indent=2, ensure_ascii=False)
    print('Added layers to diffed JSON')
else:
    print('Nakagin Capsule Tower not found in diffed JSON')
"

